/* @autogenerated */
import { TemplateViewExportActionComponent } from './template-view-export-action.component';
import { TemplateViewExportActionModule } from './template-view-export-action.module';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import {
  TEMPLATE_EXCEL_COLUMNS,
  TEMPLATE_EXCEL_SENSITIVE,
} from 'app/features/template/template/model/template-excel-columns';
import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';
import { of } from 'rxjs';

describe('TemplateViewExportActionComponent', () => {
  let repository: RepositoryMock;
  let tenantRepository: RepositoryMock;
  let interactions: InteractionMocks;
  let fixture: ComponentFixture<TemplateViewExportActionComponent>;
  let component: TemplateViewExportActionComponent;

  beforeEach(() => {
    repository = mockRepository('TemplateRepository');
    tenantRepository = mockRepository('TenantRepository');
    interactions = configureFeatureTesting({
      declarations: [TemplateViewExportActionComponent],
      repositories: [
        [TemplateRepository, repository],
        [TenantRepository, tenantRepository],
      ],
    });
    fixture = createWithoutTemplate(TemplateViewExportActionComponent);
    component = fixture.componentInstance;
  });

  afterEach(() => TestBed.resetTestingModule());

  it('creates', () => {
    expect(component).toBeTruthy();
  });

  it('is the export action, without selection', () => {
    expect(component.name).toBe('export');
    expect(component.contextual).toBeFalse();
    expect(internals(component).scope).toBe('template/template');
  });

  it('exports the shared excel columns', () => {
    expect(component.definition.name).toBe('template.template');
    expect(component.definition.columns).toBe(TEMPLATE_EXCEL_COLUMNS);
    expect(component.definition.sensitive).toBe(TEMPLATE_EXCEL_SENSITIVE);
  });

  it('reads the acl and the pages from the repository', () => {
    component.definition.source.acl().subscribe();
    expect(repository['checkAcl']).toHaveBeenCalled();
    component.definition.source.list({} as any).subscribe();
    expect(repository['list']).toHaveBeenCalledWith({});
  });

  it('names the tenant references by their display', () => {
    tenantRepository['values'].and.returnValue(of([{ uid: 'ref-1', name: 'Shown' }]));
    let names: any;
    internals(component.definition.references)
      .tenant.names(['ref-1'])
      .subscribe((found: any) => (names = found));
    expect(tenantRepository['values']).toHaveBeenCalledWith({ uids: ['ref-1'], limit: 1 });
    expect(names).toEqual({ 'ref-1': 'Shown' });
  });
});

describe('TemplateViewExportActionModule', () => {
  afterEach(() => TestBed.resetTestingModule());

  it('compiles', () => {
    moduleCompiles(TemplateViewExportActionModule, {
      repositories: [
        [TemplateRepository, mockRepository()],
        [TenantRepository, mockRepository()],
      ],
    });
  });
});
